1411: /* 计算单只标的安全边际指标；失败返回 null（页面降级为「本轮不买」） */
1412: function _mKline(secid, beg, fqt) {
1413:   const url = 'https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=' + secid +
1414:     '&fields1=f1&fields2=f51,f53&klt=101&fqt=' + fqt + '&beg=' + beg + '&end=20500101';
1415:   return fetch(url, { cache: 'no-store' }).then(r => r.json())
1416:     .then(kj => (kj && kj.data && kj.data.klines) || []);
1417: }
1418: function _mComputeOne(t, params) {
1419:   const years = params.pctYears || 3, K = params.bollK || 2;
1420:   const beg = _mDateShift(new Date().toISOString().slice(0, 10), -(years * 365 + 40)).replace(/-/g, '');
1421:   const secid = secidOf(t.code);
1422:   // 复权口径：#4 布林带用前复权(qfq, 连续无跳空)；股息率分位用不复权(raw, 除权日价格下跌是真实值，避免前复权系统性高估历史股息率)
1423:   return Promise.all([_mKline(secid, beg, 1), _mKline(secid, beg, 0)])
1424:     .then(([qfqLines, rawLines]) => {
1425:       const qfq = qfqLines.map(l => { const p = l.split(','); return { d: p[0], c: +p[1] }; });
1426:       const raw = rawLines.map(l => { const p = l.split(','); return { d: p[0], c: +p[1] }; });
1427:       if (!qfq.length) throw new Error('no kline');
1428:       const dates = qfq.map(x => x.d);
1429:       const bollCloses = qfq.map(x => x.c);           // 前复权收盘 → 布林带
1430:       const rawCloses = raw.map(x => x.c);            // 不复权收盘 → 股息率
1431:       const rawDates = raw.map(x => x.d);
1432:       const price = qfq[qfq.length - 1].c;
1433:       // 分红（每股 = PRETAX_BONUS_RMB/10）
1434:       const durl = 'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_SHAREBONUS_DET&columns=ALL&filter=(SECURITY_CODE%3D%22' +
1435:         t.code + '%22)&pageNumber=1&pageSize=100&sortColumns=EX_DIVIDEND_DATE&sortTypes=-1';
1436:       return _mJsonp(durl, 9000).catch(() => null).then(dj => {
1437:         const dividends = [];
1438:         ((dj && dj.result && dj.result.data) || []).forEach(row => {
1439:           if (row.EX_DIVIDEND_DATE && row.PRETAX_BONUS_RMB != null && +row.PRETAX_BONUS_RMB > 0)
1440:             dividends.push({ d: String(row.EX_DIVIDEND_DATE).slice(0, 10), v: +row.PRETAX_BONUS_RMB / 10 });
1441:         });
1442:         dividends.sort((a, b) => a.d < b.d ? -1 : 1);
1443:         const divDates = dividends.map(x => x.d);
1444:         const boll = [_mBoll(bollCloses, 20, K), _mBoll(bollCloses, 60, K)].filter(Boolean);
1445:         // 近 N 年股息率分位：逐交易日重建「滚动12M分红 ÷ 当时不复权价」
1446:         const lastDate = rawDates[rawDates.length - 1] || dates[dates.length - 1];
1447:         const startWin = _mDateShift(lastDate, -Math.round(years * 365));
1448:         const histY = [];
1449:         for (let i = 0; i < rawDates.length; i++) {
1450:           const dt = rawDates[i], px = rawCloses[i];
1451:           if (dt < startWin || !(px > 0)) continue;
1452:           const cutD = _mDateShift(dt, -365);
1453:           const lo = _mBisect(divDates, cutD), hi = _mBisect(divDates, dt);
1454:           let roll = 0; for (let j = lo; j < hi; j++) roll += dividends[j].v;
1455:           if (roll > 0) histY.push(roll / px * 100);
1456:         }
1457:         const cfgDps = dpsOf(t, price);
1458:         const curYld = (cfgDps && price > 0) ? cfgDps / price * 100 : null;
1459:         const avg = _mMean(histY);
1460:         // 目标股息率：
1461:         //  dynamic(默认) = max(targetYldFloor, 近3年均值 + yldPadPct)，样本不足时用 targetYldFloor 兜底
1462:         //  fixed         = 直接用 targetYldFixed（未配则 targetYld，再未配则 floor），不看均值
1463:         const fixedYld = params.targetYld || 4.8;
1464:         const pad = params.yldPadPct != null ? params.yldPadPct : 1.0;      // 安全垫（百分点）
1465:         const floor = params.targetYldFloor != null ? params.targetYldFloor : fixedYld; // 下限
1466:         const mode = params.targetYldMode || 'dynamic';
1467:         const pctEnough = histY.length >= 250;
1468:         let targetYld, targetYldConst;
1469:         if (mode === 'fixed') {
1470:           const fx = (params.targetYldFixed != null) ? +params.targetYldFixed
1471:             : (params.targetYld != null ? +params.targetYld : floor);
1472:           targetYld = fx;
1473:           targetYldConst = '固定 ' + fmt(fx, 1) + '%';
1474:         } else if (avg != null && avg > 0 && pctEnough) {
1475:           const raw = avg + pad;
1476:           if (raw >= floor) {
1477:             targetYld = raw;
1478:             targetYldConst = '均值 ' + fmt(avg, 1) + '+垫 ' + fmt(pad, 1);
1479:           } else {
1480:             targetYld = floor;
1481:             targetYldConst = '下限兜底；均值仅 ' + fmt(avg, 1);
1482:           }
1483:         } else {
1484:           targetYld = floor;
1485:           targetYldConst = '均值样本不足（' + histY.length + '日），按下限 ' + fmt(floor, 1) + '% 兜底';
1486:         }
1487:         targetYld = +targetYld.toFixed(4);
1488:         return {
1489:           code: t.code, name: t.name, asOf: lastDate, price: +price.toFixed(4),
1490:           dps: cfgDps, targetYld: targetYld, targetYldMode: mode, targetYldConst: targetYldConst,
1491:           curYld: curYld != null ? +curYld.toFixed(4) : null,
1492:           yldAvg: avg != null ? +avg.toFixed(4) : null,
1493:           yldPct: _mPctRank(histY, curYld), histYldN: histY.length,
1494:           targetBuyAbsolute: (cfgDps && targetYld > 0) ? +(cfgDps / (targetYld / 100)).toFixed(3) : null,
1495:           targetBuyConservative: (cfgDps && avg > 0) ? +(cfgDps / (avg * 1.1 / 100)).toFixed(3) : null,
1496:           boll: boll
1497:         };
1498:       });
1499:     });
